// FPGA top level for the Digilent Nexys A7 (generated by LSE)
// Use together with the matching .xdc file (pin numbers).
//   inputs  -> switches  (D3=SW[3], D2=SW[2], D1=SW[1], D0=SW[0])
//   outputs -> LEDs      (a=LED[0], b=LED[1], c=LED[2], d=LED[3], e=LED[4], f=LED[5], g=LED[6])
//   7-seg   -> right-most digit, segments a-g driven by the outputs
`timescale 1ns / 1ps

module top (
    input  wire [15:0] SW,
    output wire [15:0] LED,
    output wire        CA, CB, CC, CD, CE, CF, CG,   // segment cathodes, active low
    output wire        DP,                           // decimal point, active low
    output wire [7:0]  AN                            // digit enables, active low
);
    wire [6:0] y;   // outputs of the generated logic

    bcd7seg core (
        .D3(SW[3]),
        .D2(SW[2]),
        .D1(SW[1]),
        .D0(SW[0]),
        .a(y[0]),
        .b(y[1]),
        .c(y[2]),
        .d(y[3]),
        .e(y[4]),
        .f(y[5]),
        .g(y[6])
    );

    assign LED = {9'b0, y};
    assign {CG, CF, CE, CD, CC, CB, CA} = ~y[6:0];   // a = CA ... g = CG
    assign AN = 8'b1111_1110;                         // only digit 0 on
    assign DP = 1'b1;                                  // decimal point off
endmodule

// Structural Verilog generated by LSE (Logic Synthesis Engine)
// Design: bcd7seg   inputs: D3 D2 D1 D0   style: AND-OR
//   a = D3 + D1 + D2*D0 + D2'*D0'
//   b = D2' + D1*D0 + D1'*D0'
//   c = D2 + D1' + D0
//   d = D3 + D2'*D1 + D2'*D0' + D1*D0' + D2*D1'*D0
//   e = D2'*D0' + D1*D0'
//   f = D3 + D2*D1' + D2*D0' + D1'*D0'
//   g = D3 + D2*D1' + D2*D0' + D2'*D1
// Gates: 19  transistors: 126  levels: 3  delay: 6.50 tau
`timescale 1ns / 1ps

module bcd7seg (
    input  wire D3,
    input  wire D2,
    input  wire D1,
    input  wire D0,
    output wire a,
    output wire b,
    output wire c,
    output wire d,
    output wire e,
    output wire f,
    output wire g
);

    wire w0, D2_n, D0_n, w3, w4, D1_n, w6, w7;
    wire w8, w9, w10, w11;

    and  g0 (w0, D2, D0);
    not  g1 (D2_n, D2);
    not  g2 (D0_n, D0);
    and  g3 (w3, D2_n, D0_n);
    or   g4 (a, D3, D1, w0, w3);
    and  g5 (w4, D1, D0);
    not  g6 (D1_n, D1);
    and  g7 (w6, D1_n, D0_n);
    or   g8 (b, D2_n, w4, w6);
    or   g9 (c, D2, D1_n, D0);
    and  g10 (w7, D2_n, D1);
    and  g11 (w8, D1, D0_n);
    and  g12 (w9, D2, D1_n, D0);
    or   g13 (d, D3, w7, w3, w8, w9);
    or   g14 (e, w3, w8);
    and  g15 (w10, D2, D1_n);
    and  g16 (w11, D2, D0_n);
    or   g17 (f, D3, w10, w11, w6);
    or   g18 (g, D3, w10, w11, w7);

endmodule
